-- Named call / pickup group help (extension edit). Safe on live + new.
INSERT OR IGNORE INTO tt_help_core(pkey,displayname,htext) values ('named_call_group','Named call groups','Asterisk **named_call_group**: the pickup pool(s) this extension **belongs to**. Ringing calls on this phone are eligible for pickup by others whose **Named pickup groups** include the same token(s). Default **ALL** = whole tenant (tenant shortuid on Commit — isolated across tenants on one instance). Comma-separated department names or digit tokens (e.g. `sales` or `1,2`). Can differ from Named pickup groups.');
INSERT OR IGNORE INTO tt_help_core(pkey,displayname,htext) values ('named_pickup_group','Named pickup groups','Asterisk **named_pickup_group**: the pool(s) this extension **can pick up from** (*8 / directed pickup). Default **ALL** = whole tenant. Comma-separated department names or digit tokens (e.g. `sales` or `1,2`). Can differ from Named call groups (e.g. belong to `sales` but pick up `sales,support`). Takes effect on Commit.');
UPDATE tt_help_core SET displayname='Named call groups', htext='Asterisk **named_call_group**: the pickup pool(s) this extension **belongs to**. Ringing calls on this phone are eligible for pickup by others whose **Named pickup groups** include the same token(s). Default **ALL** = whole tenant (tenant shortuid on Commit — isolated across tenants on one instance). Comma-separated department names or digit tokens (e.g. `sales` or `1,2`). Can differ from Named pickup groups.' WHERE pkey='named_call_group';
UPDATE tt_help_core SET displayname='Named pickup groups', htext='Asterisk **named_pickup_group**: the pool(s) this extension **can pick up from** (*8 / directed pickup). Default **ALL** = whole tenant. Comma-separated department names or digit tokens (e.g. `sales` or `1,2`). Can differ from Named call groups (e.g. belong to `sales` but pick up `sales,support`). Takes effect on Commit.' WHERE pkey='named_pickup_group';
